context_info = ()
i = 0
for d in context:
    i = i + 1
    prompt = "You are extracting facts for a difficult cross-document question. Read the document below and ONLY extract information relevant to the following scenario if present.\n\nScenario to match:\n- A sporting event took place between two teams in a year between 2000 and 2010 inclusive.\n- In a year between 2015 and 2021, ahead of a title match, a defender who had played in that earlier event wrote an online blog for the website of the club he was then an assistant coach for, recalling the event and what he remembered. In that blog he indicated that the opposing team's players had all played at a high level internationally and had gone to World Cups.\n- Another individual who played for the opposing team mentioned above joined that team in the late 1990s.\n- In a retrospective article on that opposing team's official website, it was stated that in the early 2000s, this individual was brought on between minutes 45 and 55 to replace an injured player, which showed his character.\n\nIf the document clearly contains any of these pieces, extract them. If not, skip.\n\nProvide output in this exact template if any relevant info is present:\nFOUND: yes\nDOC_INDEX: <index number I give you>\nTYPE: defender_blog or opposing_player_retro (use one or both if both appear)\nDEFENDER_NAME: <name or unknown>\nASSISTANT_COACH_CLUB: <club or unknown>\nBLOG_YEAR: <year or unknown>\nORIGINAL_EVENT_YEAR: <year or range or unknown>\nORIGINAL_EVENT_TEAMS: <Team A vs Team B or unknown>\nOPPOSING_TEAM: <name or unknown>\nWORLD_CUP_NOTE_QUOTE: <short quote or paraphrase from doc supporting 'players had gone to World Cups' or similar, or unknown>\n\nOPPOSING_PLAYER_NAME: <name or unknown>\nOPPOSING_PLAYER_TEAM: <team or unknown>\nOPPOSING_PLAYER_JOIN_YEAR: <year or unknown>\nRETRO_MINUTE_SUBBED_ON: <minute or unknown>\nRETRO_MATCH_CONTEXT: <what match/competition or unknown>\nRETRO_QUOTE: <short quote supporting the substitution detail or unknown>\n\nIf nothing relevant is present, respond with exactly:\nFOUND: no\nDOC_INDEX: <index number I give you>\n\nDocument starts below.\n\nDOC_INDEX: " + str(i) + "\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    result = llm_query(prompt)
    context_info = context_info + (result,)

synthesis_prompt = "You are to determine the answer to a specific question using extractions from multiple documents.\n\nHere are the per-document extractions:\n\n" + "\n\n".join(context_info) + "\n\nTask:\n1) Identify the defender who wrote an online blog ahead of a title match (between 2015 and 2021) while serving as an assistant coach, recalling an event from 2000–2010, and noting that the opposing team’s players had gone to World Cups.\n2) Using the matched context (including the opposing player’s retrospective if present to validate the teams), determine precisely which club this defender was an assistant coach of in 2018.\n\nImportant:\n- Give only the club name as the final answer (no extra words).\n- If multiple candidates appear, choose the one that satisfies all constraints and is explicitly tied to 2018 as the year he was an assistant coach.\n- If the defender’s blog year differs from 2018 but he is clearly documented as an assistant coach of a club in 2018, answer with that club.\n- Do not explain your reasoning in the final answer; output only the club name.\n"
final_answer = llm_query(synthesis_prompt)
return_result(final_answer)